65	    private void generaPdf(ObjectMapper mapper, ObjectNode data, String outputFileName) throws Exception {
66	        JasperReport mainReport = compile(MAIN_REPORT);
67	        JasperReport subreportAllegati = compile(SUBREPORT_ALLEGATI);
68	        JasperReport subreportSoggetti = compile(SUBREPORT_SOGGETTI);
69	
70	        Map<String, Object> parameters = new HashMap<>();
71	        parameters.put(PARAM_SUBREPORT_ALLEGATI, subreportAllegati);
72	        parameters.put(PARAM_SUBREPORT_SOGGETTI, subreportSoggetti);
73	        parameters.put(PARAM_LISTA_ALLEGATI, buildListaAllegati());
74	        parameters.put(PARAM_NOME_COGNOME_UTENTE, "Alfredo Serafini");
75	
76	        byte[] jsonBytes = mapper.writeValueAsBytes(data);
77	        JsonDataSource dataSource = new JsonDataSource(new ByteArrayInputStream(jsonBytes));
78	
79	        JasperPrint jasperPrint = JasperFillManager.fillReport(mainReport, parameters, dataSource);
80	
81	        Path outputPath = writePdf(jasperPrint, outputFileName);
82	
83	    }
