85	    private JasperReport compile(String resourcePath) throws Exception {
86	        try (InputStream stream = getClass().getResourceAsStream(resourcePath)) {
87	            if (stream == null) {
88	                throw new IllegalStateException("Risorsa jrxml non trovata nel classpath: " + resourcePath);
89	            }
90	            return JasperCompileManager.compileReport(stream);
91	        }
92	    }
