94	    private Path writePdf(JasperPrint jasperPrint, String outputFileName) throws Exception {
95	        Path outputDir = Paths.get(OUTPUT_DIR);
96	        Files.createDirectories(outputDir);
97	        Path outputPath = outputDir.resolve(outputFileName);
98	
99	        try (OutputStream outputStream = Files.newOutputStream(outputPath)) {
100	            JRPdfExporter exporter = new JRPdfExporter();
101	            exporter.setExporterInput(new SimpleExporterInput(jasperPrint));
102	            exporter.setExporterOutput(new SimpleOutputStreamExporterOutput(outputStream));
103	            exporter.exportReport();
104	        }
105	        return outputPath;
106	    }
