315	    private static void configureTrustAllCertificates() {
316	        try {
317	            TrustManager[] trustAllCerts = new TrustManager[] {
318	                    new X509TrustManager() {
319	                        @Override
320	                        public X509Certificate[] getAcceptedIssuers() {
321	                            return new X509Certificate[0];
322	                        }
323	
324	                        @Override
325	                        public void checkClientTrusted(X509Certificate[] certs, String authType) {
326	                            // nessuna verifica: necessario solo per caricare il logo remoto in test
327	                        }
328	
329	                        @Override
330	                        public void checkServerTrusted(X509Certificate[] certs, String authType) {
331	                            // nessuna verifica: necessario solo per caricare il logo remoto in test
332	                        }
333	                    }
334	            };
335	
336	            SSLContext sslContext = SSLContext.getInstance("TLS");
337	            sslContext.init(null, trustAllCerts, new java.security.SecureRandom());
338	            HttpsURLConnection.setDefaultSSLSocketFactory(sslContext.getSocketFactory());
339	
340	            HostnameVerifier allHostsValid = (hostname, session) -> true;
341	            HttpsURLConnection.setDefaultHostnameVerifier(allHostsValid);
342	        } catch (Exception e) {
343	            // in assenza di rete il logo remoto non verrà caricato, ma il resto del PDF sì
344	        }
345	    }
