public class GeneratorePdfMarketing {
    private static final String MAIN_REPORT = "/marketing/template_marketing2027_istanza.jrxml";
    private static final String SUBREPORT_ALLEGATI = "/marketing/allegati_subreport_istanza.jrxml";
    private static final String SUBREPORT_SOGGETTI = "/marketing/soggetti_subreport_istanza.jrxml";

    private static final String PARAM_SUBREPORT_ALLEGATI = "marketing/allegati_subreport_istanza.jrxml";
    private static final String PARAM_SUBREPORT_SOGGETTI = "marketing/soggetti_subreport_istanza.jrxml";
    private static final String PARAM_LISTA_ALLEGATI = "listaAllegati";
    private static final String PARAM_NOME_COGNOME_UTENTE = "nomeCognomeUtente";

    private static final String OUTPUT_DIR = "target/pdf";
    private static final String OUTPUT_FILE = "template_marketing2027_istanza_test.pdf";
    private static final String OUTPUT_FILE_SOGGETTI_AGGREGATI = "template_marketing2027_istanza_test_soggettiAggregati.pdf";

    private static final String FORMA_CANDIDATURA_SINGOLA = "in forma SINGOLA";
    private static final String FORMA_CANDIDATURA_AGGREGATA = "in forma AGGREGATA in qualita di soggetto CAPOFILA";

    private static final String FIRMATARIO = "Regione Puglia , Rita Emi De Matteis , Alfredo Serafini";
    private static final String NOME_FILE_ALLEGATO = "PDF di test con sigillo 2_signed.pdf";
    private static final String IMPRONTA_ALLEGATO = "7yo9Z8sy69TRrilZJf91ewS+LoB+fRYdU7tdK+6V59Y=";
    public void execute() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        ObjectNode data = buildData(mapper);
        data.put("formaCandidatura", FORMA_CANDIDATURA_SINGOLA);

        generaPdf(mapper, data, OUTPUT_FILE);
    }

    private void generaPdf(ObjectMapper mapper, ObjectNode data, String outputFileName) throws Exception {
        JasperReport mainReport = compile(MAIN_REPORT);
        JasperReport subreportAllegati = compile(SUBREPORT_ALLEGATI);
        JasperReport subreportSoggetti = compile(SUBREPORT_SOGGETTI);

        Map<String, Object> parameters = new HashMap<>();
        parameters.put(PARAM_SUBREPORT_ALLEGATI, subreportAllegati);
        parameters.put(PARAM_SUBREPORT_SOGGETTI, subreportSoggetti);
        parameters.put(PARAM_LISTA_ALLEGATI, buildListaAllegati());
        parameters.put(PARAM_NOME_COGNOME_UTENTE, "Alfredo Serafini");

        byte[] jsonBytes = mapper.writeValueAsBytes(data);
        JsonDataSource dataSource = new JsonDataSource(new ByteArrayInputStream(jsonBytes));

        JasperPrint jasperPrint = JasperFillManager.fillReport(mainReport, parameters, dataSource);

        Path outputPath = writePdf(jasperPrint, outputFileName);

    }

    private JasperReport compile(String resourcePath) throws Exception {
        try (InputStream stream = getClass().getResourceAsStream(resourcePath)) {
            if (stream == null) {
                throw new IllegalStateException("Risorsa jrxml non trovata nel classpath: " + resourcePath);
            }
            return JasperCompileManager.compileReport(stream);
        }
    }

    private Path writePdf(JasperPrint jasperPrint, String outputFileName) throws Exception {
        Path outputDir = Paths.get(OUTPUT_DIR);
        Files.createDirectories(outputDir);
        Path outputPath = outputDir.resolve(outputFileName);

        try (OutputStream outputStream = Files.newOutputStream(outputPath)) {
            JRPdfExporter exporter = new JRPdfExporter();
            exporter.setExporterInput(new SimpleExporterInput(jasperPrint));
            exporter.setExporterOutput(new SimpleOutputStreamExporterOutput(outputStream));
            exporter.exportReport();
        }
        return outputPath;
    }

